    """Return fresh total, completed and pending counts.

    Counts are computed on each call; the store is never mutated.
    """
    total = len(self._tasks)
    completed = sum(1 for task in self._tasks.values() if task.completed is True)
    return {
        "total": total,
        "completed": completed,
        "pending": total - completed,
    }

